import json
from fractions import Fraction as F

vals = [F(k, 2) for k in range(-20, 21)]
q_implies_p = True   # (a>2 and b>2) -> a+b>4
p_implies_q = True   # a+b>4 -> (a>2 and b>2)
counter_p_not_q = None
counter_q_not_p = None

for a in vals:
    for b in vals:
        P = a + b > 4
        Q = a > 2 and b > 2
        if Q and not P:
            q_implies_p = False
            counter_q_not_p = (str(a), str(b))
        if P and not Q:
            p_implies_q = False
            if counter_p_not_q is None:
                counter_p_not_q = (str(a), str(b))

# P = "a+b>4" is the condition; Q = "a>2 and b>2" is the statement.
# P necessary for Q iff Q -> P; P sufficient for Q iff P -> Q.
sufficient = p_implies_q
necessary = q_implies_p

if sufficient and not necessary:
    ans = "A"
elif necessary and not sufficient:
    ans = "B"
elif necessary and sufficient:
    ans = "C"
else:
    ans = "D"

print(json.dumps({
    "final_answer": ans,
    "evidence": {
        "sufficient": sufficient,
        "necessary": necessary,
        "counterexample_P_not_Q": counter_p_not_q,
        "counterexample_Q_not_P": counter_q_not_p,
        "grid": "half-integers in [-10,10], exact fractions"
    }
}))
